    # Validate
    required_keys = ["id", "topic", "question", "difficulty", "diagram", "hinglish_explanation", "real_life_example", "how_to_answer"]
    errors = []
    for q in questions:
        for key in required_keys:
            if key not in q:
                errors.append(f"Q{q.get('id','?')}: missing '{key}'")
        if q.get("difficulty") not in ["Easy", "Medium", "Hard"]:
            errors.append(f"Q{q['id']}: invalid difficulty '{q.get('difficulty')}'")

    if errors:
        print(f"ERRORS: {len(errors)}")
        for e in errors[:10]:
            print(f"  {e}")
    else:
        print("All questions validated successfully!")

    # Write JSON
    output_path = "/projects/sandbox/library-management-system-/ml_frameworks_250_interview_questions.json"
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(questions, f, indent=2, ensure_ascii=False)
    print(f"\nWritten to: {output_path}")

    # Stats
    print(f"\n{'='*50}")
    print(f"STATISTICS:")
    print(f"{'='*50}")
    print(f"Total questions: {len(questions)}")

    diff_counts = {}
    for q in questions:
        diff_counts[q["difficulty"]] = diff_counts.get(q["difficulty"], 0) + 1
    print(f"\nDifficulty Distribution:")
    for d in ["Easy", "Medium", "Hard"]:
        print(f"  {d}: {diff_counts.get(d, 0)}")

    # Framework coverage
    sklearn_count = sum(1 for q in questions if q["id"] <= 80)
    pytorch_count = sum(1 for q in questions if 81 <= q["id"] <= 170)
    tf_count = sum(1 for q in questions if q["id"] >= 171)
    print(f"\nPer-Framework Coverage:")
    print(f"  Scikit-learn: {sklearn_count} questions (IDs 1-80)")
    print(f"  PyTorch: {pytorch_count} questions (IDs 81-170)")
    print(f"  TensorFlow/Keras: {tf_count} questions (IDs 171-250)")
    print(f"\nDone! File size: {os.path.getsize(output_path)/1024/1024:.2f} MB")
